"""Fixed stdin transport envelope; NOT authorized for workstation execution."""
import base64
import hashlib
import json
import sys

LENGTH = 29948
SHA256 = 'c02a0b0565cf6c77af2effdcef2961b7ff567dff898b462a9be56af3999c79f1'
PAYLOAD = ''


def unpack():
    data = base64.b64decode(PAYLOAD, validate=True)
    if len(data) != LENGTH or hashlib.sha256(data).hexdigest() != SHA256:
        raise RuntimeError('launcher_transport_binding')
    return data


if __name__ == '__main__':
    try:
        data = unpack()
    except Exception as exc:
        print(json.dumps(dict(terminal='INCOMPLETE', authorization=False,
                              ready_for_build=False, vendor_run=False,
                              error=type(exc).__name__ + ':' + str(exc))))
        sys.exit(1)
    exec(compile(data, '<hash-bound-launcher>', 'exec'),
         dict(__name__='__main__', LAUNCHER_BINDING=dict(length=LENGTH, sha256=SHA256)))
